#ifndef ONLINE_JUDGE
#define debug(...) std::cerr << __LINE__ << ": [", __DEBUG_UTIL__::printer(#__VA_ARGS__, __VA_ARGS__)
#define debugArr(...) std::cerr << __LINE__ << ": [", __DEBUG_UTIL__::printerArr(#__VA_ARGS__, __VA_ARGS__)
#else
#define debug(...)
#define debugArr(...)
#endif
const int maxn = 1e5 + 5;
vector<pair<int, int>> adj[maxn];
int par[maxn];
int par1[maxn][505];
int find(int n) {
    return par[n] == n ? n : par[n] = find(par[n]);
}
bool unite(int u, int v) {
    int x = find(u);
    int y = find(v);
    if(x != y) {
        par[x] = y;
        return true;
    }
    return false;
}
int find1(int n, int k) {
    debug(n, k);
    return par1[n][k] == n ? n : par1[n][k] = find1(par1[n][k], k);
}
bool unite1(int u, int v, int k) {
    int x = find1(u, k);
    int y = find1(v, k);
    if(x != y) {
        par1[x][k] = y;
        return true;
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    //freopen("UPGRADE.INP", "r", stdin);
    //freopen("UPGRADE.OUT", "w", stdout);
    int n, m, W;
    cin >> n >> m >> W;
    vector<tuple<int, int, int>> ed, oed;
    for(int i = 1; i <= m; i++) {
        int x, y, z;
        cin >> x >> y >> z;
        adj[x].push_back({y, z});
        adj[y].push_back({x, z});
        ed.emplace_back(z, x, y);
        oed.emplace_back(z, x, y);
    }
    for(int i = 1; i <= n; i++) {
        for(int k = 0; k < 505; k++) {
            par1[i][k] = i;
        }
        par[i] = i;
    }
    vector<tuple<int, int, int>> ed1;
    sort(ed.begin(), ed.end(), greater<tuple<int, int, int>>());
    long long tot = 0;
    for(auto [w, u, v] : ed) {
        if(unite(u, v)) {
            ed1.emplace_back(w, u, v);
            tot += w;
        }
    }
    for(auto [w, u, v] : ed1) {
        for(int i = 2; i <= w; i++) {
            unite1(u, v, i);
        }
    }
    int q;
    cin >> q;
    while(q--) {
        int t, x;
        cin >> t >> x;
        auto [w, u, v] = oed[t - 1];
        int nw = w + x;

        for(int k = w + 1; k <= nw; k ++) {
            if(unite1(u, v, k)) {
                tot++;
            }
        }
        oed[t - 1] = {nw, u, v};
        cout << tot << '\n';
    }
}